<?php
namespace App\Http\Controllers;
use App\Http\Requests\ProductRequest; use App\Models\Product; use Illuminate\Http\Request;
class ProductController extends Controller { public function index(Request $request){$products=Product::query()->when($request->search,fn($q,$s)=>$q->where('name','like',"%$s%"))->latest()->paginate(15)->withQueryString();return view('resources.index',compact('products'))->with('resource','products');} public function create(){return view('resources.form',['resource'=>'products','record'=>new Product]);} public function store(ProductRequest $request){Product::create($request->validated());return redirect()->route('products.index')->with('success','Product/service created.');} public function edit(Product $product){return view('resources.form',['resource'=>'products','record'=>$product]);} public function update(ProductRequest $request,Product $product){$product->update($request->validated());return redirect()->route('products.index')->with('success','Product/service updated.');} public function destroy(Product $product){$product->delete();return back()->with('success','Product/service deleted.');} }
